const events = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json || {};
  if (body.object !== 'page') continue;

  for (const entry of body.entry || []) {
    // `standby` arrives when another app owns the thread (Handover Protocol).
    const messagingEvents = entry.messaging || entry.standby || [];

    for (const event of messagingEvents) {
      const message = event.message || {};

      // Echoes are the page's own outgoing messages; delivery/read/reaction
      // events carry no user text. Replying to them loops or fails.
      if (message.is_echo) continue;
      if (event.delivery || event.read || event.reaction || event.message_edit) continue;

      const senderId = event.sender && event.sender.id;
      const pageId = (event.recipient && event.recipient.id) || entry.id;
      if (!senderId || senderId === pageId) continue;

      let messageType = 'text';
      let textContent = message.text || '';
      let mediaUrl = '';

      if (event.postback) {
        textContent = event.postback.payload || event.postback.title || '';
      }

      if (message.quick_reply && message.quick_reply.payload) {
        textContent = message.quick_reply.payload;
      }

      const attachment = (message.attachments || [])[0];
      if (attachment) {
        if (attachment.type === 'audio') messageType = 'audio';
        else if (attachment.type === 'image') messageType = 'image';
        mediaUrl = (attachment.payload && attachment.payload.url) || '';
      }

      if (!textContent && !mediaUrl) continue;

      events.push({
        json: {
          sender_id: senderId,
          page_id: pageId,
          message_type: messageType,
          raw_text: textContent,
          media_url: mediaUrl
        }
      });
    }
  }
}

return events;
